\documentclass{standalone}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows} %% Can be useful, not essential
\usetikzlibrary{intersections} %% Can be useful, not essential
\usepgfplotslibrary{fillbetween} %% Can be useful, not essential
%\usepackage[top=1in,bottom=1in,right=1in,left=1in]{geometry}
\begin{document}
	\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
	\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
	\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
	\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
	\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
	\definecolor{rustred}{rgb}{0.784,0.392,0.149}
	\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

    \begin{tikzpicture}[scale = 3,cap=round,>=latex]
    \def\ccolor{deepskyblue};

        \draw[->] (-1.5cm,0cm) -- (1.5cm,0cm) node[right,fill=white] {$x$};
        \draw[->] (0cm,-1.5cm) -- (0cm,1.5cm) node[above,fill=white] {$y$};

        % draw the unit circle
        \draw[very thick,color=\ccolor] (0cm,0cm) circle(1cm);

        \foreach \x in {0,90,180,270,360} {
                % lines from center to point
                \draw[gray] (0cm,0cm) -- (\x:1cm);
                % dots at each point
                \filldraw[black] (\x:1cm) circle(0.4pt);
}


	  \foreach \x/\xtext in {
                % draw each angle in degrees
           90/90^\circ,
	   180/180^\circ,
	   270/270^\circ,
	   360/0^\circ
        }
                \draw (\x:0.6cm) node[fill=white] {$\xtext$};

        % draw each angle in radians
        \foreach \x/\xtext in {
            90/\frac{\pi}{2},
            180/\pi,
            270/\frac{3\pi}{2},
            360/0}
                \draw (\x:0.85cm) node[fill=white] {\large{$\xtext$}};


        % draw the horizontal and vertical coordinates
        % the placement is better this way
        \draw (-1.25cm,0cm) node[above=1pt] {$(-1,0)$}
              (1.25cm,0cm)  node[above=1pt] {$(1,0)$}
              (0cm,-1.25cm) node[fill=white] {$(0,-1)$}
              (0cm,1.25cm)  node[fill=white] {$(0,1)$};
    \end{tikzpicture}
\end{document}

